    "src/store/userTransactionsSlice.js": "import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const initialState = {
  transactions: [],
};

export const userTransactionsSlice = createSlice({
  name: 'userTransactions',
  initialState,
  reducers: {
    addTransaction: (state, action) => {
      state.transactions.push({ id: uuidv4(), ...action.payload });
    },
    editTransaction: (state, action) => {
      const index = state.transactions.findIndex(t => t.id === action.payload.id);
      if (index !== -1) {
        state.transactions[index] = { ...state.transactions[index], ...action.payload };
      }
    },
    deleteTransaction: (state, action) => {
      state.transactions = state.transactions.filter(t => t.id !== action.payload);
    },
  },
});

export const { addTransaction, editTransaction, deleteTransaction } = userTransactionsSlice.actions;

export default userTransactionsSlice.reducer;",
    "src/store/spendingHabitsSlice.js": "import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  categories: {
    food: 0,
    transport: 0,
    housing: 0,
    entertainment: 0,
    utilities: 0,
    others: 0,
  },
  totalSpent: 0,
};

export const spendingHabitsSlice = createSlice({
  name: 'spendingHabits',
  initialState,
  reducers: {
    updateSpending: (state, action) => {
      const { category, amount } = action.payload;
      if (state.categories[category] !== undefined) {
        state.categories[category] += amount;
      } else {
        state.categories.others += amount; // Fallback for uncategorized
      }
      state.totalSpent += amount;
    },
    resetSpending: (state) => {
      state.categories = initialState.categories;
      state.totalSpent = 0;
    },
  },
});

export const { updateSpending, resetSpending } = spendingHabitsSlice.actions;

export default spendingHabitsSlice.reducer;",
