    "src/screens/SavingsInvestment.jsx": "import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import SavingsGoalWidget from '../components/SavingsGoalWidget';
import InvestmentAdviceCard from '../components/InvestmentAdviceCard';
import { addGoal, deleteGoal } from '../store/financialGoalsSlice';
import { setRiskTolerance } from '../store/riskToleranceSlice';
import { v4 as uuidv4 } from 'uuid';

const SavingsInvestment = () => {
  const dispatch = useDispatch();
  const financialGoals = useSelector((state) => state.financialGoals.goals);
  const riskTolerance = useSelector((state) => state.riskTolerance);

  const [goalName, setGoalName] = useState('');
  const [targetAmount, setTargetAmount] = useState('');
  const [riskLevelInput, setRiskLevelInput] = useState(riskTolerance.level);

  const handleAddGoal = (e) => {
    e.preventDefault();
    if (!goalName || !targetAmount || parseFloat(targetAmount) <= 0) return;

    dispatch(addGoal({
      name: goalName,
      targetAmount: parseFloat(targetAmount),
      currentAmount: 0,
      startDate: new Date().toISOString().split('T')[0],
      id: uuidv4()
    }));
    setGoalName('');
    setTargetAmount('');
  };

  const handleDeleteGoal = (id) => {
    if (window.confirm('Are you sure you want to delete this goal?')) {
      dispatch(deleteGoal(id));
    }
  };

  const handleRiskToleranceChange = (e) => {
    const newLevel = e.target.value;
    setRiskLevelInput(newLevel);
    let description = '';
    if (newLevel === 'low') description = 'Low risk tolerance, conservative investments.';
    else if (newLevel === 'moderate') description = 'Moderate risk tolerance, balanced portfolio.';
    else description = 'High risk tolerance, aggressive growth investments.';
    dispatch(setRiskTolerance({ level: newLevel, description }));
  };

  const getInvestmentAdvice = (level) => {
    switch (level) {
      case 'low':
        return "Consider stable assets like bonds, high-yield savings accounts, and blue-chip stocks. Prioritize capital preservation over aggressive growth.";
      case 'moderate':
        return "A balanced portfolio with a mix of stocks, bonds, and diversified mutual funds is suitable. Explore growth stocks with established track records.";
      case 'high':
        return "Aggressive growth strategies focusing on volatile stocks, emerging markets, and potentially cryptocurrencies. Be prepared for higher fluctuations.";
      default:
        return "Adjust your risk tolerance to get tailored advice.";
    }
  };

  return (
    <div className="space-y-8">
      <h1 className="text-4xl font-extrabold text-gray-900 dark:text-gray-100 mb-6">Savings & Investment Planning</h1>

      {/* Add New Goal Form */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-gray-100 mb-4">Set a New Savings Goal</h2>
        <form onSubmit={handleAddGoal} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label htmlFor="goalName" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Goal Name</label>
            <input
              type="text"
              id="goalName"
              value={goalName}
              onChange={(e) => setGoalName(e.target.value)}
              className="mt-1 block w-full border border-gray-300 dark:border-gray-700 rounded-md shadow-sm p-2 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:ring-indigo-500 focus:border-indigo-500"
              placeholder="e.g., Down Payment for House"
              required
            />
          </div>
          <div>
            <label htmlFor="targetAmount" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Target Amount</label>
            <input
              type="number"
              id="targetAmount"
              value={targetAmount}
              onChange={(e) => setTargetAmount(e.target.value)}
              className="mt-1 block w-full border border-gray-300 dark:border-gray-700 rounded-md shadow-sm p-2 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:ring-indigo-500 focus:border-indigo-500"
              placeholder="e.g., 50000"
              min="0.01"
              step="0.01"
              required
            />
          </div>
          <div className="md:col-span-2">
            <button
              type="submit"
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-colors duration-200"
            >
              Add Goal
            </button>
          </div>
        </form>
      </div>

      {/* Financial Goals */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-gray-100 mb-4">My Savings Goals</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {financialGoals.length === 0 ? (
            <p className="text-gray-600 dark:text-gray-400 md:col-span-3">No savings goals set yet.</p>
          ) : (
            financialGoals.map((goal) => (
              <div key={goal.id} className="relative group">
                <SavingsGoalWidget goal={goal} />
                <button
                  onClick={() => handleDeleteGoal(goal.id)}
                  className="absolute top-2 right-2 p-1 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-200"
                  aria-label="Delete goal"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Risk Tolerance & Investment Advice */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-gray-100 mb-4">Investment Advice</h2>
        <div className="mb-6">
          <label htmlFor="riskTolerance" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Your Risk Tolerance</label>
          <select
            id="riskTolerance"
            value={riskLevelInput}
            onChange={handleRiskToleranceChange}
            className="mt-1 block w-full md:w-1/2 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm p-2 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 focus:ring-indigo-500 focus:border-indigo-500"
          >
            <option value="low">Low</option>
            <option value="moderate">Moderate</option>
            <option value="high">High</option>
          </select>
        </div>
        <InvestmentAdviceCard
          advice={getInvestmentAdvice(riskTolerance.level)}
          riskLevel={riskTolerance.level}
        />
      </div>
    </div>
  );
};

