import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { addReminder, markAsPaid, deleteReminder } from '../store/billRemindersSlice';
import { v4 as uuidv4 } from 'uuid';

const BillReminders = () => {
  const dispatch = useDispatch();
  const reminders = useSelector((state) => state.billReminders.reminders);

  const [billName, setBillName] = useState('');
  const [amount, setAmount] = useState('');
  const [dueDate, setDueDate] = useState('');

  const handleAddReminder = (e) => {
    e.preventDefault();
    if (!billName || !amount || parseFloat(amount) <= 0 || !dueDate) return;

    dispatch(addReminder({
      name: billName,
      amount: parseFloat(amount),
      dueDate,
      isPaid: false,
      paidDate: null,
      id: uuidv4()
    }));

    setBillName('');
    setAmount('');
    setDueDate('');
  };

  const sortedReminders = [...reminders].sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate));

  return (
    <div className="space-y-8">
      <h1 className="text-4xl font-extrabold text-gray-900 dark:text-gray-100 mb-6">Bill Reminders</h1>

      {/* Add New Reminder Form */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
