                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100">${reminder.amount.toFixed(2)}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-gray-100">{reminder.dueDate}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">
                      <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${reminder.isPaid ? 'bg-green-100 text-green-800 dark:bg-green-700 dark:text-green-100' : 'bg-yellow-100 text-yellow-800 dark:bg-yellow-700 dark:text-yellow-100'}`}>
                        {reminder.isPaid ? `Paid (${reminder.paidDate})` : 'Pending'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {!reminder.isPaid && (
                        <button
                          onClick={() => dispatch(markAsPaid(reminder.id))}
                          className="text-indigo-600 hover:text-indigo-900 dark:text-indigo-400 dark:hover:text-indigo-200 mr-4 transition-colors duration-200"
                        >
                          Mark as Paid
                        </button>
                      )}
                      <button
                        onClick={() => dispatch(deleteReminder(reminder.id))}
                        className="text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-200 transition-colors duration-200"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default BillReminders;

frontend.src/screens/Analytics.jsx:
import React from 'react';
import { useSelector } from 'react-redux';

const Analytics = () => {
  const transactions = useSelector((state) => state.userTransactions.transactions);
  const spendingHabits = useSelector((state) => state.spendingHabits.categories);

  // Basic calculations for analytics
  const totalIncome = transactions.filter(t => t.type === 'income').reduce((acc, t) => acc + t.amount, 0);
  const totalExpenses = transactions.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0);
  const netCashFlow = totalIncome + totalExpenses; // expenses are negative, so this naturally calculates net

  return (
    <div className="space-y-8">
      <h1 className="text-4xl font-extrabold text-gray-900 dark:text-gray-100 mb-6">Reports & Analytics</h1>

      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
          <h3 className="text-xl font-semibold text-gray-900 dark:text-gray-100 mb-2">Total Income</h3>
          <p className="text-3xl font-bold text-green-600 dark:text-green-400">${totalIncome.toFixed(2)}</p>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
          <h3 className="text-xl font-semibold text-gray-900 dark:text-gray-100 mb-2">Total Expenses</h3>
          <p className="text-3xl font-bold text-red-600 dark:text-red-400">${Math.abs(totalExpenses).toFixed(2)}</p>
        </div>
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
          <h3 className="text-xl font-semibold text-gray-900 dark:text-gray-100 mb-2">Net Cash Flow</h3>
          <p className={`text-3xl font-bold ${netCashFlow >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>${netCashFlow.toFixed(2)}</p>
        </div>
      </div>

      {/* Spending Habits by Category */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-gray-100 mb-4">Spending Habits by Category</h2>
        {Object.keys(spendingHabits).every(key => spendingHabits[key] === 0) ? (
          <p className="text-gray-600 dark:text-gray-400">No spending data available yet.</p>
        ) : (
          <div className="space-y-4">
            {Object.entries(spendingHabits).map(([category, amount]) => {
              if (amount === 0) return null;
              const percentage = (Math.abs(amount) / Math.abs(totalExpenses)) * 100 || 0;
              return (
                <div key={category}>
                  <div className="flex justify-between items-center mb-1">
                    <span className="text-gray-700 dark:text-gray-300 capitalize">{category}</span>
                    <span className="font-medium text-gray-900 dark:text-gray-100">${Math.abs(amount).toFixed(2)} ({percentage.toFixed(1)}%)</span>
                  </div>
                  <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2.5">
                    <div className="bg-indigo-600 h-2.5 rounded-full" style={{ width: `${percentage}%` }}></div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Predictive Cash Flow Analysis (Placeholder) */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-gray-100 mb-4">Predictive Cash Flow Analysis</h2>
        <p className="text-gray-600 dark:text-gray-400 mb-4">
          Based on your historical income and expenses, and upcoming bills, your predicted cash flow for the next 30 days is:
        </p>
        <p className="text-3xl font-bold text-blue-600 dark:text-blue-400">$1200.00 Surplus</p>
        <p className="text-sm text-gray-500 dark:text-gray-400 mt-2">AI suggests you are on track to meet your short-term savings goals.</p>
        {/* A graph or more detailed projection would go here */}
        <div className="mt-6 h-48 bg-gray-200 dark:bg-gray-700 rounded-lg flex items-center justify-center">
          <p className="text-gray-500 dark:text-gray-400">Graph Placeholder: Cash Flow Projection</p>
        </div>
      </div>
    </div>
  );
};

export default Analytics;

