import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  categories: {
    food: 0,
    transport: 0,
    housing: 0,
    entertainment: 0,
    utilities: 0,
    others: 0,
  },
  totalSpent: 0,
};

export const spendingHabitsSlice = createSlice({
  name: 'spendingHabits',
  initialState,
  reducers: {
    updateSpending: (state, action) => {
      const { category, amount } = action.payload;
      if (state.categories[category] !== undefined) {
        state.categories[category] += amount;
      } else {
        state.categories.others += amount; // Fallback for uncategorized
      }
      state.totalSpent += amount;
    },
    resetSpending: (state) => {
      state.categories = initialState.categories;
      state.totalSpent = 0;
    },
  },
});

export const { updateSpending, resetSpending } = spendingHabitsSlice.actions;

export default spendingHabitsSlice.reducer;

