import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const initialState = {
  goals: [],
};

export const financialGoalsSlice = createSlice({
  name: 'financialGoals',
  initialState,
  reducers: {
    addGoal: (state, action) => {
      state.goals.push({ id: uuidv4(), ...action.payload });
    },
    updateGoal: (state, action) => {
      const index = state.goals.findIndex(g => g.id === action.payload.id);
      if (index !== -1) {
        state.goals[index] = { ...state.goals[index], ...action.payload };
      }
    },
    deleteGoal: (state, action) => {
      state.goals = state.goals.filter(g => g.id !== action.payload);
    },
    addContribution: (state, action) => {
      const { id, amount } = action.payload;
      const goal = state.goals.find(g => g.id === id);
      if (goal) {
        goal.currentAmount += amount;
      }
    },
  },
});

export const { addGoal, updateGoal, deleteGoal, addContribution } = financialGoalsSlice.actions;

export default financialGoalsSlice.reducer;

