import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const initialState = {
  reminders: [],
};

export const billRemindersSlice = createSlice({
  name: 'billReminders',
  initialState,
  reducers: {
    addReminder: (state, action) => {
      state.reminders.push({ id: uuidv4(), ...action.payload });
    },
    markAsPaid: (state, action) => {
      const reminder = state.reminders.find(r => r.id === action.payload);
      if (reminder) {
        reminder.isPaid = true;
        reminder.paidDate = new Date().toISOString().split('T')[0];
      }
    },
    deleteReminder: (state, action) => {
      state.reminders = state.reminders.filter(r => r.id !== action.payload);
    },
  },
});

export const { addReminder, markAsPaid, deleteReminder } = billRemindersSlice.actions;

export default billRemindersSlice.reducer;

