import React from 'react';
import { useDispatch } from 'react-redux';
import { addContribution } from '../store/financialGoalsSlice';

const SavingsGoalWidget = ({ goal }) => {
  const dispatch = useDispatch();
  const progress = (goal.currentAmount / goal.targetAmount) * 100;

  const handleAddContribution = () => {
    const contribution = parseFloat(prompt('Enter contribution amount:'));
    if (!isNaN(contribution) && contribution > 0) {
      dispatch(addContribution({ id: goal.id, amount: contribution }));
    }
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
      <h3 className="text-xl font-semibold text-gray-900 dark:text-gray-100 mb-2">{goal.name}</h3>
      <p className="text-gray-600 dark:text-gray-400 mb-4">Target: ${goal.targetAmount.toFixed(2)}</p>
      <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2.5 mb-2">
        <div
          className="bg-indigo-600 h-2.5 rounded-full"
          style={{ width: `${Math.min(100, progress)}%` }}
        ></div>
      </div>
      <p className="text-sm text-gray-700 dark:text-gray-300">${goal.currentAmount.toFixed(2)} of ${goal.targetAmount.toFixed(2)} ({progress.toFixed(2)}%)</p>
      <button
        onClick={handleAddContribution}
        className="mt-4 w-full bg-indigo-500 hover:bg-indigo-600 text-white font-bold py-2 px-4 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-colors duration-200"
      >
        Add Contribution
      </button>
    </div>
  );
};

export default SavingsGoalWidget;

