import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { addReminder, markAsPaid, deleteReminder } from '../store/billRemindersSlice';
import { v4 as uuidv4 } from 'uuid';

const BillReminders = () => {
